def repair(row):
 if 'error' not in row:return row
 used={r['sourceUrl'] for r in rows if r['product']==row['product'] and 'error' not in r}
 for url in manifest[row['product']]:
  if url in used or url==row['sourceUrl']:continue
  try:
   data=urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'}),timeout=15).read()
   im=Image.open(io.BytesIO(data));im.load();assert min(im.size)>100;im.thumbnail((1600,1600))
   path=Path(f"src/assets/images/products/{row['product']}/{row['index']}.webp")
   im.save(path,'WEBP',quality=88)
   return dict(product=row['product'],index=row['index'],path=str(path),sourceUrl=url,width=im.width,height=im.height)
  except Exception:continue
 return row
fixed=list(concurrent.futures.ThreadPoolExecutor(max_workers=6).map(repair,rows))
Path('work/catalog-distinct/images.json').write_text(json.dumps(fixed,indent=2))
for row in fixed:
 if 'error' in row:print(row['product'],row['index'],row['error'])
print('Downloaded:',sum('error' not in row for row in fixed), '/', len(fixed))

